"""Private GEXOption Sora chat UI: 40-symbol selector, price overview, chatbot."""
from http.server import BaseHTTPRequestHandler
import sys,os
sys.path.insert(0,os.path.dirname(__file__))
from swing_access import require_access
HTML = "<!doctype html><html lang=\"ko\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>GEXOption · 소라 AI</title><style>\n:root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0b1422;color:#edf4ff}*{box-sizing:border-box}body{margin:0}header{padding:10px 14px;border-bottom:1px solid #34445c;display:flex;align-items:center;justify-content:space-between}h1{font-size:19px;margin:0}.tiny{color:#a9bcd6;font-size:12px}.shell{max-width:1200px;margin:auto}.layout{display:grid;grid-template-columns:260px minmax(0,1fr);gap:12px;padding:12px}.sidebar,.workspace{border:1px solid #34445c;border-radius:12px;background:#132139}.sidebar{padding:12px;max-height:85dvh;overflow:auto}.sidebar button{width:100%;margin:3px 0;text-align:left}.workspace{display:flex;flex-direction:column;height:calc(100dvh - 80px);min-height:560px;overflow:hidden}.toolbar{display:flex;gap:8px;align-items:center;padding:9px;border-bottom:1px solid #34445c}select,button,input{font:inherit;color:#ecf3ff;background:#263952;border:1px solid #49627f;border-radius:9px;padding:10px}button{cursor:pointer}button:disabled{opacity:.5}.toolbar select{max-width:60%;min-width:0}.chart{flex:1;min-height:0;padding:10px;display:flex;flex-direction:column;gap:8px;border-bottom:1px solid #34445c}.plot{flex:1;min-height:70px;width:100%;border:1px solid #30425c;border-radius:9px;background:#0d1b2c}svg{width:100%;height:100%}.chat{flex:2;min-height:0;display:flex;flex-direction:column}.messages{flex:1;overflow:auto;padding:12px;display:flex;flex-direction:column;gap:10px}.bubble{max-width:89%;padding:10px 12px;border-radius:12px;background:#293a52;white-space:pre-wrap;line-height:1.5;font-size:14px}.bubble.user{align-self:flex-end;background:#166452}.entry{display:flex;gap:7px;padding:9px;border-top:1px solid #34445c}.entry input{flex:1;min-width:0}.muted{color:#afc0d6}.warning{color:#ffd590}.hidden{display:none}.flag{font-size:12px;background:#283c56;padding:5px 8px;border-radius:10px}.search{width:100%;margin-bottom:8px}@media(max-width:680px){header{padding:8px 12px}.layout{display:block;padding:0}.sidebar{display:none}.workspace{height:calc(100dvh - 51px);min-height:0;border-radius:0;border:0}.chart{flex:1}.chat{flex:2}.toolbar{padding:6px}.chart{padding:7px}.bubble{font-size:14px}}\n</style></head><body><div class=\"shell\"><header><h1>GEXOption · 소라 AI</h1><span class=\"flag\">LEADER 40 · 교육용 베타</span></header><div class=\"layout\"><aside class=\"sidebar\"><strong>LEADER 40</strong><p class=\"tiny\">초기 후보 · 등급 검증 전</p><input id=\"search\" class=\"search\" placeholder=\"종목 검색\" aria-label=\"종목 검색\"><div id=\"stockList\"></div></aside><main class=\"workspace\"><div class=\"toolbar\"><label for=\"ticker\" class=\"tiny\">종목</label><select id=\"ticker\" aria-label=\"종목 선택\"></select><select id=\"tf\" aria-label=\"차트 주기\"><option value=\"1d\">일봉</option><option value=\"30m\">30분봉</option><option value=\"5m\">5분봉</option></select></div><section class=\"chart\" aria-label=\"차트\"><div class=\"tiny\" id=\"chartStatus\">차트 조회 전</div><div class=\"plot\"><svg id=\"plot\" viewBox=\"0 0 320 115\" preserveAspectRatio=\"none\" aria-label=\"가격 추이 선 그래프\"><text x=\"12\" y=\"60\" fill=\"#afc0d6\" font-size=\"12\">데이터 확인 중…</text></svg></div><div class=\"tiny\">지연 OHLCV 기반 가격 추이 · 실시간 데이터 아님 · Wall 미확인</div></section><section class=\"chat\" aria-label=\"소라 대화\"><div class=\"messages\" id=\"messages\" role=\"log\" aria-live=\"polite\"></div><form id=\"chatForm\" class=\"entry\"><input id=\"question\" maxlength=\"1200\" placeholder=\"소라에게 차트 분석 질문...\" autocomplete=\"off\" aria-label=\"질문\"><button id=\"send\" type=\"submit\">전송</button></form></section></main></div></div><script>\n\"use strict\";\nconst GROUPS={\"A+\":[\"NVDA\",\"MSFT\",\"GOOGL\",\"AMZN\",\"META\",\"TSLA\",\"PLTR\",\"AVGO\",\"GEV\",\"TSM\"],\"A\":[\"MU\",\"CRDO\",\"ANET\",\"VRT\",\"ETN\",\"FIX\",\"APP\",\"LITE\",\"DELL\",\"NFLX\"],\"B\":[\"SNDK\",\"STX\",\"WDC\",\"INTC\",\"MXL\",\"MRVL\",\"COHR\",\"VIAV\",\"CIEN\",\"TER\"],\"C\":[\"IREN\",\"NBIS\",\"CIFR\",\"CLSK\",\"RKLB\",\"OKLO\",\"SMR\",\"RGTI\",\"QBTS\",\"SOUN\"]};\nconst $=id=>document.getElementById(id);const conversations=new Map();let chosen=\"AMZN\",pending=false,chartSeq=0;\nfunction add(role,text){const div=document.createElement(\"div\");div.className=\"bubble\"+(role===\"user\"?\" user\":\"\");div.textContent=(role===\"user\"?\"나: \":\"소라: \")+text;$(\"messages\").append(div);$(\"messages\").scrollTop=$(\"messages\").scrollHeight}\nfunction paintChat(){const items=conversations.get(chosen)||[];$(\"messages\").replaceChildren();if(!items.length)add(\"assistant\",chosen+\" 분석 준비됐습니다. 먼저 일봉 기울기와 위치를 확인하고, 30분봉 진입 구조 또는 5분봉 CORE 헤지 분석을 설명하겠습니다. 현재 데이터 연결 전에는 실시간 가격을 단정하지 않습니다.\");else items.forEach(x=>add(x.role,x.content))}\nfunction renderStockList(){const root=$(\"stockList\");root.replaceChildren();const q=$(\"search\").value.trim().toUpperCase();for(const [grade,names] of Object.entries(GROUPS)){for(const name of names.filter(s=>s.includes(q))){const b=document.createElement(\"button\");b.textContent=grade+\" · \"+name;b.addEventListener(\"click\",()=>choose(name));root.append(b)}}}\nfunction choose(ticker){if(pending)return;chosen=ticker;$(\"ticker\").value=ticker;paintChat();updateChart()}\nconst all=Object.entries(GROUPS).flatMap(([grade,names])=>names.map(symbol=>({grade,symbol})));for(const x of all){const opt=document.createElement(\"option\");opt.value=x.symbol;opt.textContent=x.symbol+\" · \"+x.grade;$(\"ticker\").append(opt)}\nfunction trace(bars){const svg=$(\"plot\");svg.replaceChildren();const last=bars.slice(-55);if(last.length<2)throw Error(\"가격 데이터 부족\");const ys=last.map(x=>Number(x.close));if(ys.some(x=>!Number.isFinite(x)))throw Error(\"가격 데이터 오류\");const lo=Math.min(...ys),hi=Math.max(...ys),span=hi-lo||1;const pts=ys.map((v,i)=>[8+(i/(ys.length-1))*304,100-(v-lo)/span*85]);const poly=document.createElementNS(\"http://www.w3.org/2000/svg\",\"polyline\");poly.setAttribute(\"points\",pts.map(v=>v.join(\",\")).join(\" \"));poly.setAttribute(\"fill\",\"none\");poly.setAttribute(\"stroke\",\"#5be0ad\");poly.setAttribute(\"stroke-width\",\"2\");svg.append(poly)}\nasync function updateChart(){const ticker=chosen,tf=$(\"tf\").value,seq=++chartSeq;$(\"chartStatus\").textContent=ticker+\" \"+tf+\" · 조회 중\";$(\"plot\").replaceChildren();try{const r=await fetch(\"/api/swing_radar_chart?ticker=\"+encodeURIComponent(ticker)+\"&tf=\"+encodeURIComponent(tf),{credentials:\"same-origin\",cache:\"no-store\"});if(!r.ok)throw Error(\"차트 API HTTP \"+r.status);const j=await r.json();if(seq!==chartSeq)return;trace(j.bars||[]);$(\"chartStatus\").textContent=ticker+\" · \"+tf+\" · 마지막 완료봉 \"+(j.last_bar_utc||\"시각 미확인\")+\" UTC\";}catch(e){if(seq!==chartSeq)return;$(\"chartStatus\").textContent=ticker+\" · 차트 확인 불가: \"+e.message+\" (데이터 없는 경우 표시하지 않음)\";}}\nasync function submit(e){e.preventDefault();if(pending)return;const text=$(\"question\").value.trim();if(!text)return;pending=true;$(\"send\").disabled=true;const t=chosen;const history=(conversations.get(t)||[]).slice(-8);const full=conversations.get(t)||[];full.push({role:\"user\",content:text});conversations.set(t,full);add(\"user\",text);$(\"question\").value=\"\";try{const r=await fetch(\"/api/sora_chat\",{method:\"POST\",credentials:\"same-origin\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({ticker:t,message:text,history})});const j=await r.json();if(!r.ok)throw Error(j.error||\"응답 실패\");const answer=String(j.answer||\"\").trim();if(!answer)throw Error(\"빈 응답\");full.push({role:\"assistant\",content:answer});if(chosen===t)add(\"assistant\",answer);}catch(err){if(chosen===t)add(\"assistant\",\"연결 오류: \"+err.message+\" · AI 연결을 먼저 확인해 주세요.\");}finally{pending=false;$(\"send\").disabled=false}}\n$(\"ticker\").addEventListener(\"change\",e=>choose(e.target.value));$(\"tf\").addEventListener(\"change\",updateChart);$(\"search\").addEventListener(\"input\",renderStockList);$(\"chatForm\").addEventListener(\"submit\",submit);$(\"ticker\").value=chosen;renderStockList();paintChat();updateChart();\n</script></body></html>"
class handler(BaseHTTPRequestHandler):
 def do_GET(self):
  if not require_access(self):return
  body=HTML.encode("utf-8")
  self.send_response(200)
  self.send_header("Content-Type","text/html; charset=utf-8")
  self.send_header("Content-Length",str(len(body)))
  self.send_header("Cache-Control","no-store")
  self.send_header("X-Content-Type-Options","nosniff")
  self.send_header("Content-Security-Policy","default-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; connect-src 'self'; frame-ancestors 'self'")
  self.end_headers();self.wfile.write(body)
